<template><BioNexusDialog ref="dialog" size="wide" dialog-class="payment-method-dialog" :prevent-close="saving||dirty" :kicker="mode==='create'?'Nuevo registro':'Editar registro'" :title="mode==='create'?'Crear forma de pago':'Editar forma de pago'" @before-close="requestClose" @close="resetValidation"><section class="payment-method-body" @keydown.tab.capture="preserveDialogViewportOnTab"><BioNexusFormErrors :errors="errorMessage"/><BioNexusSectionPanel title="Información de la forma de pago" icon="payments" description="Define la descripción y las monedas habilitadas para registrar pagos." variant="accent"><div class="payment-information-grid"><div class="payment-description-column"><BioNexusFormField label="Descripción" field-id="type-payment-description" :error="descriptionError" :help="draft.description.length + ' de 100 caracteres'" required><input id="type-payment-description" ref="firstInput" v-model="draft.description" class="bio-nexus-field" maxlength="100" @input="syncDirty"></BioNexusFormField></div><fieldset class="payment-section currency-section"><legend>Monedas disponibles</legend><div class="currency-list"><div v-for="currency in currencyOptions" :key="currency.id" class="currency-row"><BioNexusCheckbox v-model="draft.currencyIds" :value="currency.id" :label="currency.code" :help="currency.name" @change="syncCurrency"/><label class="default-currency-option" :class="{'default-currency-option-disabled':!draft.currencyIds.includes(currency.id)}"><input v-model.number="draft.defaultCurrencyId" type="radio" name="default-payment-currency" :value="currency.id" :disabled="!draft.currencyIds.includes(currency.id)" @change="syncDirty"><span>Predeterminada</span></label></div></div><p v-if="currencyError" class="field-error">{{currencyError}}</p></fieldset></div></BioNexusSectionPanel><BioNexusSectionPanel title="Campos adicionales" icon="view_list" description="Configura la información complementaria solicitada al registrar un pago." variant="accent"><section class="payment-section fields-section"><header><div><strong>Campos adicionales</strong><small>Define la información complementaria que deberá completar el usuario al registrar un pago, por ejemplo referencia, banco, teléfono o fecha.</small></div><BioNexusActionButton type="button" variant="secondary" icon="create" :disabled="saving" @click="addField">Agregar campo</BioNexusActionButton></header><p v-if="!draft.fields.length" class="bio-nexus-empty-state">Esta forma de pago no solicita datos adicionales.</p><article v-for="(field,index) in draft.fields" :key="field.clientKey" class="field-card"><span class="order-number">{{index+1}}</span><div class="field-grid"><BioNexusFormField label="Etiqueta" :field-id="'field-label-'+index" :error="fieldError(index,'label')" :help="field.label.length + ' de 100 caracteres'" required><input :id="'field-label-'+index" v-model="field.label" class="bio-nexus-field" maxlength="100" @input="syncDirty"></BioNexusFormField><BioNexusFormField label="Tipo" :field-id="'field-type-'+index" help="Define el tipo de información que deberá completar el usuario." required><BioNexusSearchableSelect :id="'field-type-'+index" v-model="field.fieldType" :options="fieldTypes" :disabled="saving" placeholder="Seleccione un tipo" search-placeholder="Buscar tipo..." empty-text="Sin tipos coincidentes" @change="syncDirty" /></BioNexusFormField><BioNexusFormField label="Ayuda" :field-id="'field-help-'+index" :help="field.helpText.length + ' de 255 caracteres'"><input :id="'field-help-'+index" v-model="field.helpText" class="bio-nexus-field" maxlength="255" @input="syncDirty"></BioNexusFormField><BioNexusCheckbox :model-value="field.isRequired" class="required-check" label="Obligatorio" @pointerdown.capture="captureDialogViewport" @update:model-value="setFieldRequired(field,$event)"/></div><div class="field-actions"><BioNexusActionButton icon="arrow_upward" icon-only shape="circle" size="sm" variant="secondary" label="Subir" :disabled="index===0||saving" @click="moveField(index,-1)"/><BioNexusActionButton icon="arrow_downward" icon-only shape="circle" size="sm" variant="secondary" label="Bajar" :disabled="index===draft.fields.length-1||saving" @click="moveField(index,1)"/><BioNexusActionButton icon="delete" icon-only shape="circle" size="sm" variant="danger" label="Quitar campo" :disabled="saving" @click="removeField(index)"/></div></article><p v-if="fieldsError" class="field-error">{{fieldsError}}</p></section></BioNexusSectionPanel></section><template #footer><BioNexusActionButton variant="secondary" icon="cancel" :disabled="saving" @click="requestClose">Cancelar</BioNexusActionButton><BioNexusActionButton variant="primary" :icon="mode==='create'?'create':'save'" :loading="saving" :disabled="submitDisabled" @click="submit">{{mode==='create'?'Crear':'Guardar'}}</BioNexusActionButton></template></BioNexusDialog><BioNexusConfirmDialog ref="discardDialog"/></template>
<script setup>import{computed,nextTick,reactive,ref}from'vue';import BioNexusDialog from'@/components/ui/BioNexusDialog.vue';import BioNexusFormField from'@/components/ui/BioNexusFormField.vue';import BioNexusSearchableSelect from'@/components/ui/BioNexusSearchableSelect.vue';import BioNexusActionButton from'@/components/ui/BioNexusActionButton.vue';import BioNexusCheckbox from'@/components/ui/BioNexusCheckbox.vue';import BioNexusConfirmDialog from'@/components/ui/BioNexusConfirmDialog.vue';import BioNexusFormErrors from'@/components/ui/BioNexusFormErrors.vue';import BioNexusSectionPanel from'@/components/ui/BioNexusSectionPanel.vue';const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean,currencyOptions:{type:Array,default:()=>[]}}),emit=defineEmits(['submit']),dialog=ref(null),discardDialog=ref(null),firstInput=ref(null),mode=ref('create'),current=ref(null),attempted=ref(false),errorMessage=ref(''),original=ref(''),dirty=ref(false),sequence=ref(0),draft=reactive({description:'',currencyIds:[],defaultCurrencyId:0,fields:[]}),draftTechnicalCode=ref(createTechnicalCodeSuffix());const fieldTypes=[{value:'text',label:'Texto'},{value:'number',label:'Número'},{value:'date',label:'Fecha'},{value:'phone',label:'Teléfono'},{value:'reference',label:'Referencia'},{value:'bank',label:'Banco'},{value:'boolean',label:'Sí / No'}];function normalizeTechnicalCodeName(value){
  return String(value??"")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,"-")
    .replace(/^-+|-+$/g,"")
    .slice(0,24)||"forma-pago";
}
function createTechnicalCodeSuffix(){return Math.random().toString(36).slice(2,8)}
function createTechnicalCode(description,suffix){return `payment-${normalizeTechnicalCodeName(description)}-${suffix}`}const fieldCode=(label,index)=>String(label||`campo-${index+1}`).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,42)||`campo-${index+1}`;const values=computed(()=>({code:mode.value==='create'?createTechnicalCode(draft.description,draftTechnicalCode.value):current.value?.code,description:draft.description.trim(),displayOrder:mode.value==='create'?0:Number(current.value?.displayOrder)||0,currencyIds:[...new Set(draft.currencyIds.map(Number))],defaultCurrencyId:Number(draft.defaultCurrencyId)||0,fields:draft.fields.map((field,index)=>({code:field.code||fieldCode(field.label,index),label:field.label.trim(),fieldType:field.fieldType,isRequired:Boolean(field.isRequired),minLength:field.minLength??null,maxLength:field.maxLength??null,inputMask:field.inputMask||null,validationPattern:field.validationPattern||null,helpText:field.helpText.trim()||null,catalogSource:field.fieldType==='bank'?'banks':null,isActive:field.isActive!==false}))}));const signature=computed(()=>JSON.stringify({...values.value,code:mode.value==='create'?'NEW':values.value.code})),descriptionError=computed(()=>attempted.value&&!draft.description.trim()?'La descripción es obligatoria.':''),currencyError=computed(()=>!attempted.value?'':!draft.currencyIds.length?'Selecciona al menos una moneda.':!draft.currencyIds.includes(draft.defaultCurrencyId)?'Selecciona una moneda predeterminada válida.':''),fieldsError=computed(()=>attempted.value&&draft.fields.some(x=>!x.label.trim())?'Completa la etiqueta de todos los campos.':''),submitDisabled=computed(()=>props.saving||!dirty.value||(mode.value==='create'?!props.canCreate:!props.canUpdate)||!draft.description.trim()||!draft.currencyIds.length||!draft.currencyIds.includes(draft.defaultCurrencyId)||draft.fields.some(x=>!x.label.trim()));function makeField(value={}){return{clientKey:++sequence.value,id:Number(value.id)||0,code:value.code||'',label:value.label||'',fieldType:value.fieldType||'text',isRequired:Boolean(value.isRequired),minLength:value.minLength??null,maxLength:value.maxLength??null,inputMask:value.inputMask||'',validationPattern:value.validationPattern||'',helpText:value.helpText||'',isActive:value.isActive!==false}}function assign(row){draft.description=row?.description||'';draft.currencyIds=[...(row?.currencyIds||[])];draft.defaultCurrencyId=Number(row?.defaultCurrencyId)||0;draft.fields=(row?.fields||[]).map(makeField)}async function show(){original.value=signature.value;dirty.value=false;await dialog.value?.open();await nextTick();original.value=signature.value;dirty.value=false;firstInput.value?.focus()}async function openCreate(){mode.value='create';current.value=null;draftTechnicalCode.value=createTechnicalCodeSuffix();assign(null);attempted.value=false;errorMessage.value='';original.value='';await show()}async function openEdit(row){mode.value='edit';current.value=row;assign(row);attempted.value=false;errorMessage.value='';await show()}function addField(){draft.fields.push(makeField());syncDirty()}function removeField(index){draft.fields.splice(index,1);syncDirty()}function moveField(index,delta){const target=index+delta;if(target<0||target>=draft.fields.length)return;const[row]=draft.fields.splice(index,1);draft.fields.splice(target,0,row);syncDirty()}function syncCurrency(){if(draft.currencyIds.length&&!draft.currencyIds.includes(draft.defaultCurrencyId))draft.defaultCurrencyId=Number(draft.currencyIds[0]);syncDirty()}let requiredViewportSnapshot=[];
function captureDialogViewport(event){
  const dialogElement=event?.currentTarget?.closest?.("dialog")||document.querySelector("dialog.payment-method-dialog[open]");
  const candidates=dialogElement?[dialogElement,...dialogElement.querySelectorAll("*")]:[];
  requiredViewportSnapshot=candidates.filter(element=>element.scrollHeight>element.clientHeight).map(element=>({element,top:element.scrollTop,left:element.scrollLeft}));
}
function restoreRequiredViewport(){
  for(const state of requiredViewportSnapshot){
    if(!state.element?.isConnected)continue;
    state.element.scrollTop=state.top;
    state.element.scrollLeft=state.left;
  }
}
function preserveDialogViewportOnTab(event){
  captureDialogViewport(event);
  requestAnimationFrame(()=>{
    restoreRequiredViewport();
    requestAnimationFrame(()=>{
      restoreRequiredViewport();
      requiredViewportSnapshot=[];
    });
  });
}async function setFieldRequired(field,value){
  field.isRequired=Boolean(value);
  syncDirty();
  await nextTick();
  restoreRequiredViewport();
  requestAnimationFrame(()=>{
    restoreRequiredViewport();
    requestAnimationFrame(()=>{
      restoreRequiredViewport();
      requiredViewportSnapshot=[];
    });
  });
}
function syncDirty(){errorMessage.value="";dirty.value=signature.value!==original.value}function fieldError(index,name){return attempted.value&&name==='label'&&!draft.fields[index]?.label.trim()?'La etiqueta es obligatoria.':''}function submit(){attempted.value=true;if(descriptionError.value||currencyError.value||fieldsError.value)return;if(submitDisabled.value)return;emit('submit',{mode:mode.value,record:current.value,values:values.value})}async function requestClose(){if(props.saving)return;if(dirty.value){const confirmed=await discardDialog.value?.ask({kicker:"Confirmación",title:"Descartar cambios",message:"Hay cambios sin guardar. ¿Deseas salir y descartarlos?",icon:"warning",variant:"danger",confirmIcon:"delete",confirmText:"Sí, salir y descartar cambios",cancelText:"Cancelar"});if(!confirmed)return}dialog.value?.close()}function close(){dialog.value?.close()}function resetValidation(){attempted.value=false;dirty.value=false;errorMessage.value=""}defineExpose({openCreate,openEdit,close,setError:value=>errorMessage.value=String(value||''),clearError:()=>errorMessage.value=''})</script>
<style scoped>.payment-method-body{display:grid;gap:var(--bio-nexus-space-4);font:400 13px var(--bio-nexus-font-family,Inter,Roboto,Arial,sans-serif)}.payment-information-grid{display:grid;grid-template-columns:minmax(300px,.9fr) minmax(520px,1.35fr);gap:var(--bio-nexus-space-4);align-items:start}.payment-description-column{min-width:0;padding-top:1px}.payment-section{display:grid;gap:8px;margin:0;padding:12px;border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-md)}.payment-section legend,.fields-section header strong{font-size:14px;font-weight:700}.currency-section{min-width:0}.currency-list{display:grid;gap:8px}.currency-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:var(--bio-nexus-space-4);min-height:44px;padding:5px 8px;border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-sm);background:var(--bio-nexus-color-surface-soft)}.currency-row :deep(.bio-nexus-checkbox){width:100%}.default-currency-option{display:inline-flex;align-items:center;gap:7px;min-height:32px;color:var(--bio-nexus-color-text);font-weight:600;white-space:nowrap;cursor:pointer}.default-currency-option input{width:17px;height:17px;margin:0;accent-color:var(--bio-nexus-color-primary)}.default-currency-option-disabled{cursor:not-allowed;opacity:.55}.currency-row small,.fields-section header small{color:var(--bio-nexus-color-text-muted)}.fields-section header{display:flex;align-items:center;justify-content:space-between}.fields-section header div{display:grid}.field-card{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:9px;align-items:start;padding:9px;border:1px solid var(--bio-nexus-color-border);border-radius:8px;background:var(--bio-nexus-color-surface-soft)}.order-number{display:grid;place-items:center;width:32px;height:32px;margin:14px auto 0;border:1px solid var(--bio-nexus-color-border-strong);border-radius:50%;font-weight:700}.field-grid{display:grid;grid-template-columns:1.2fr .8fr 1.2fr auto;gap:8px;align-items:start}.field-grid :deep(.bio-nexus-field-group){grid-template-rows:auto 42px minmax(32px,auto);align-content:start}.field-grid :deep(.bio-nexus-field-help){min-height:32px;line-height:16px}.required-check{align-self:center;margin-top:0;min-height:42px}.required-check :deep(.bio-nexus-checkbox){align-items:center}.field-actions{display:flex;align-items:center;gap:4px;margin-top:13px}.field-actions button{min-width:34px;height:34px;border:1px solid var(--bio-nexus-color-border);border-radius:50%;background:var(--bio-nexus-color-surface);color:var(--bio-nexus-color-primary)}.field-actions .remove{display:grid;place-items:center;width:34px;min-width:34px;padding:0;border-radius:50%;color:var(--bio-nexus-color-danger)}.field-actions .remove :deep(.bio-nexus-icon),.field-actions .remove :deep(.material-symbols-rounded){width:18px;height:18px;font-size:18px}.field-error{margin:0;color:var(--bio-nexus-color-danger);font-size:12px}@media(max-width:900px){.payment-information-grid{grid-template-columns:1fr}.field-grid{grid-template-columns:1fr 1fr}.field-card{grid-template-columns:34px 1fr}.field-actions{grid-column:2}}@media(max-width:620px){.field-grid{grid-template-columns:1fr}.field-card{grid-template-columns:1fr}.field-actions{grid-column:1}}</style><style>dialog.bio-nexus-dialog.payment-method-dialog{width:min(1100px,calc(100vw - 32px))!important;max-height:calc(100dvh - 32px)!important}</style>
